/// Returns a tuple containing:
/// - the 0-based index of the first out-of-order element (1-based in the answer),
/// - the 0-based index of the element to swap with (1-based in the answer),
/// - the number of swaps performed (always 1 if a swap happened),
/// - a boolean indicating whether a swap was performed.
///
/// If the slice is already sorted, returns (None, None, 0, false).
pub fn can_arrange(arr: &Vec<i32>) -> (Option<usize>, Option<usize>, usize, bool) {
    // We'll iterate through the array, comparing each element with its next one
    for i in 0..arr.len() - 1 {
