```csharp
using System;
using System.Collections.Generic;

// Helper: Factorial or sum of 1..n (whichever is smaller)
int FactorialOrSum(int n)
{
    if (n == 0)
        return 0;
    if (n == 1)
        return 1;

    long factorial = 1;
    int sum = 0;
    for (int i = 2; i <= n; i++)
    {
        factorial *= i;
        sum += i;
    }

    // Use long to avoid overflow for large n
    if (factorial < sum)
        return (int)factorial;
    else
        return sum;
}

// Helper: Fibonacci number (0-based)
int Fibonacci(int n)
{
    if (n == 0)
        return 0;
    if (n == 1)
        return 1;

    long a = 0, b = 1;
    for (int i = 2; i <= n; i++)
    {
        long temp = a + b;
        a = b;
        b = temp;
    }
    return (int)b;
}

// Main function: returns a list of (FactorialOrSum(i), Fibonacci(i)) for i=1..n,
// then pads with Nones for i = n+1 .. m-1
List<object[]> F(int n, int m)
{
    List<object[]> results = new List<object[]>();
    for (int i = 1; i <= n; i++)
    {
        int val1 = FactorialOrSum(i);
        int val2 = Fibonacci(i);
        results.Add(new object[] { val1, val2 });
    }

    // Pad with None for indices from n to m-1 (exclusive of n)
    for (int i = n; i < m; i++)
    {
        results.Add(new object[] { null });
    }

    return results;
}

